changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE SCHEMA IF NOT EXISTS "log";
CREATE TABLE IF NOT EXISTS "log".user_log ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4 ( ) NOT NULL, user_id UUID, reason TEXT, first_name TEXT, last_name TEXT, old_version JSON, new_version JSON, different_fields TEXT, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
